struct Base {
    int base_id;     // Allocated first
    char base_flag;  // Follows base_id (may involve padding)
};
struct Derived : Base {
    // Base members are laid out contiguously first
    long derived_value;  // Starts at offset >= sizeof(Base)
    short derived_status;
};
// Single Inheritance Layout Rule:
// [ Base Data (members + padding) ] [ Derived Data (members + padding) ]
